-- Convert Design Studio quote requests into commercial quotations and confirmed orders.
create sequence public.seq_factory_quotation start 1;
create table public.factory_quotations(quotation_id uuid primary key default gen_random_uuid(),quotation_no text not null unique,rfq_id uuid not null unique references public.rfqs(id),design_project_id uuid not null references public.design_projects(id),design_code text not null,design_name text not null,customer_id uuid not null references public.customers(customer_id),product_id uuid not null references public.products(product_id),quantity numeric not null check(quantity>0),unit_rate numeric not null check(unit_rate>=0),currency text not null default'PKR',valid_until date not null,terms text,status text not null default'SENT'check(status in('DRAFT','SENT','ACCEPTED','DECLINED','EXPIRED')),production_order_id uuid references public.production_orders(production_order_id),created_at timestamptz not null default now(),created_by text not null default'system',updated_at timestamptz not null default now(),updated_by text);
alter table public.factory_quotations enable row level security;create policy factory_read_quotations on public.factory_quotations for select using(has_factory_role(auth.uid(),array['admin','production_manager','accounts','viewer']));
create or replace function public.list_factory_quote_sources()returns table(rfq_id uuid,design_project_id uuid,design_code text,design_name text,family text,revision_no int,contact_name text,company text,email text,quantity text,quantity_unit text,target_price text,target_date date)language sql stable security definer set search_path=public as $$select r.id,p.id,p.design_code,p.name,p.family::text,p.current_revision,r.contact_name,r.company,r.email,r.quantity,r.quantity_unit,r.target_price,r.target_date from rfqs r join design_projects p on p.id=r.project_id where has_factory_role(auth.uid(),array['admin','production_manager','accounts','viewer'])and r.kind='quote'and r.status in('Submitted','Under Review')and not exists(select 1 from factory_quotations q where q.rfq_id=r.id)order by r.created_at$$;
create or replace function public.create_factory_quotation(p_rfq uuid,p_customer uuid,p_product uuid,p_quantity numeric,p_unit_rate numeric,p_currency text,p_valid_until date,p_terms text default null)returns uuid language plpgsql security definer set search_path=public as $$declare v_id uuid;v_project uuid;v_code text;v_name text;v_no text;begin if not has_factory_role(auth.uid(),array['admin','production_manager','accounts'])then raise exception'not authorized';end if;if p_quantity<=0 or p_unit_rate<0 then raise exception'invalid quantity or rate';end if;if p_valid_until<current_date then raise exception'valid until date cannot be in the past';end if;select p.id,p.design_code,p.name into v_project,v_code,v_name from rfqs r join design_projects p on p.id=r.project_id where r.id=p_rfq and r.kind='quote'and r.status in('Submitted','Under Review')for update of r,p;if not found then raise exception'quote request is unavailable';end if;v_no:='QT-'||to_char(current_date,'YYYYMMDD')||'-'||lpad(nextval('seq_factory_quotation')::text,4,'0');insert into factory_quotations(quotation_no,rfq_id,design_project_id,design_code,design_name,customer_id,product_id,quantity,unit_rate,currency,valid_until,terms,created_by)values(v_no,p_rfq,v_project,v_code,v_name,p_customer,p_product,p_quantity,p_unit_rate,upper(coalesce(nullif(trim(p_currency),''),'PKR')),p_valid_until,nullif(trim(p_terms),''),auth.uid()::text)returning quotation_id into v_id;update rfqs set status='Quoted'where id=p_rfq;update design_projects set status='Quoted',updated_at=now()where id=v_project;insert into audit_log(user_id,action,entity_type,entity_id,new_value)values(auth.uid(),'Quotation Issued','factory_quotations',v_id,jsonb_build_object('quotation_no',v_no,'design_code',v_code,'amount',p_quantity*p_unit_rate));return v_id;end$$;
create or replace function public.accept_factory_quotation(p_quotation uuid)returns uuid language plpgsql security definer set search_path=public as $$declare q factory_quotations;v_order uuid;begin if not has_factory_role(auth.uid(),array['admin','production_manager'])then raise exception'not authorized';end if;select*into q from factory_quotations where quotation_id=p_quotation and status='SENT'for update;if not found then raise exception'quotation is not available for acceptance';end if;if q.valid_until<current_date then update factory_quotations set status='EXPIRED',updated_at=now(),updated_by=auth.uid()::text where quotation_id=p_quotation;raise exception'quotation has expired';end if;v_order:=create_factory_order(q.customer_id,q.product_id,q.quantity,'Accepted quotation '||q.quotation_no,current_date);update factory_quotations set status='ACCEPTED',production_order_id=v_order,updated_at=now(),updated_by=auth.uid()::text where quotation_id=p_quotation;update design_projects set status='Order Confirmed',updated_at=now()where id=q.design_project_id;update rfqs set status='Accepted'where id=q.rfq_id;insert into audit_log(user_id,action,entity_type,entity_id,new_value)values(auth.uid(),'Quotation Accepted','factory_quotations',p_quotation,jsonb_build_object('quotation_no',q.quotation_no,'production_order_id',v_order));return v_order;end$$;
create or replace function public.decline_factory_quotation(p_quotation uuid,p_reason text)returns text language plpgsql security definer set search_path=public as $$declare q factory_quotations;begin if not has_factory_role(auth.uid(),array['admin','production_manager','accounts'])then raise exception'not authorized';end if;if nullif(trim(p_reason),'')is null then raise exception'decline reason is required';end if;select*into q from factory_quotations where quotation_id=p_quotation and status='SENT'for update;if not found then raise exception'quotation is not available';end if;update factory_quotations set status='DECLINED',updated_at=now(),updated_by=auth.uid()::text where quotation_id=p_quotation;update rfqs set status='Declined'where id=q.rfq_id;insert into audit_log(user_id,action,entity_type,entity_id,old_value,new_value,reason)values(auth.uid(),'Quotation Declined','factory_quotations',p_quotation,jsonb_build_object('status','SENT'),jsonb_build_object('status','DECLINED'),trim(p_reason));return'DECLINED';end$$;
revoke all on function public.list_factory_quote_sources()from public;revoke all on function public.create_factory_quotation(uuid,uuid,uuid,numeric,numeric,text,date,text)from public;revoke all on function public.accept_factory_quotation(uuid)from public;revoke all on function public.decline_factory_quotation(uuid,text)from public;grant execute on function public.list_factory_quote_sources()to authenticated;grant execute on function public.create_factory_quotation(uuid,uuid,uuid,numeric,numeric,text,date,text)to authenticated;grant execute on function public.accept_factory_quotation(uuid)to authenticated;grant execute on function public.decline_factory_quotation(uuid,text)to authenticated;
